-- Phase 7A: private timetable and final-readiness planning. No launch, sale, settlement or fulfilment occurs here.
DO $$ BEGIN
 IF to_regclass('public.festival_sponsorship_plans') IS NULL OR to_regclass('public.festival_stages') IS NULL THEN
  RAISE EXCEPTION 'festival_timetable_incompatible_schema';
 END IF;
END $$;

CREATE TABLE public.festival_timetable_plans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_company_id uuid UNIQUE NOT NULL REFERENCES public.festival_companies(id) ON DELETE CASCADE,sponsorship_plan_id uuid UNIQUE NOT NULL REFERENCES public.festival_sponsorship_plans(id),timezone text NOT NULL,status text NOT NULL DEFAULT 'not_started' CHECK(status IN('not_started','structure_generated','artist_scheduling','operations_scheduling','conflict_review','readiness_review','ready_for_launch_preparation')),planning_version integer NOT NULL DEFAULT 1 CHECK(planning_version>0),schedule_generation_version integer NOT NULL DEFAULT 1,readiness_formula_version integer NOT NULL DEFAULT 1,weather_contingencies jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE public.festival_timetable_days(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,festival_date date NOT NULL,day_number integer NOT NULL CHECK(day_number>0),public_open_at timestamptz,public_close_at timestamptz,artist_access_at timestamptz,staff_access_at timestamptz,supplier_access_at timestamptz,site_clear_at timestamptz,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','locked')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(festival_timetable_plan_id,festival_date),UNIQUE(festival_timetable_plan_id,day_number),CHECK(public_open_at IS NULL OR (staff_access_at<=public_open_at AND supplier_access_at<=public_open_at AND public_open_at<public_close_at AND public_close_at<site_clear_at)));
CREATE TABLE public.festival_stage_operating_windows(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_day_id uuid NOT NULL REFERENCES public.festival_timetable_days(id) ON DELETE CASCADE,stage_id uuid NOT NULL REFERENCES public.festival_stages(id),opens_at timestamptz NOT NULL,performances_start_at timestamptz NOT NULL,performances_end_at timestamptz NOT NULL,curfew_at timestamptz NOT NULL,soundcheck_start_at timestamptz,soundcheck_end_at timestamptz,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','locked')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(festival_timetable_day_id,stage_id),CHECK(opens_at<=performances_start_at AND performances_start_at<performances_end_at AND performances_end_at<=curfew_at));
CREATE TABLE public.festival_stage_slots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,festival_timetable_day_id uuid NOT NULL REFERENCES public.festival_timetable_days(id) ON DELETE CASCADE,stage_id uuid NOT NULL REFERENCES public.festival_stages(id),slot_type text NOT NULL CHECK(slot_type IN('performance','changeover','soundcheck','opening_ceremony','closing_ceremony','sponsor_activation','media','maintenance','reserved')),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','locked','cancelled')),sequence_number integer NOT NULL CHECK(sequence_number>0),headline_slot boolean NOT NULL DEFAULT false,reserved_for_artist_booking_id uuid REFERENCES public.festival_artist_bookings(id),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),slot_version integer NOT NULL DEFAULT 1,CHECK(starts_at<ends_at),UNIQUE(festival_timetable_day_id,stage_id,sequence_number));
CREATE EXTENSION IF NOT EXISTS btree_gist;
ALTER TABLE public.festival_stage_slots ADD CONSTRAINT festival_stage_slots_no_overlap EXCLUDE USING gist(stage_id WITH =,tstzrange(starts_at,ends_at,'[)') WITH &&) WHERE(status<>'cancelled');
CREATE TABLE public.festival_artist_performance_slots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,stage_slot_id uuid UNIQUE NOT NULL REFERENCES public.festival_stage_slots(id),artist_booking_id uuid UNIQUE NOT NULL REFERENCES public.festival_artist_bookings(id),artist_source text NOT NULL CHECK(artist_source IN('profile','band','npc')),profile_id uuid REFERENCES public.profiles(id),band_id uuid REFERENCES public.bands(id),npc_artist_id uuid,performance_duration_minutes integer NOT NULL CHECK(performance_duration_minutes BETWEEN 10 AND 180),arrival_required_at timestamptz NOT NULL,backstage_call_at timestamptz NOT NULL,stage_call_at timestamptz NOT NULL,performance_status text NOT NULL DEFAULT 'scheduled' CHECK(performance_status IN('scheduled','removed')),suitability_snapshot jsonb NOT NULL DEFAULT '{}',availability_snapshot jsonb NOT NULL DEFAULT '{}',activity_block_references jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),allocation_version integer NOT NULL DEFAULT 1,CHECK(num_nonnulls(profile_id,band_id,npc_artist_id)=1));
CREATE TABLE public.festival_artist_soundchecks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,artist_performance_slot_id uuid UNIQUE NOT NULL REFERENCES public.festival_artist_performance_slots(id),stage_id uuid NOT NULL REFERENCES public.festival_stages(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,soundcheck_type text NOT NULL CHECK(soundcheck_type IN('full','line_check','shared_backline','headliner_extended','none')),status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(starts_at<ends_at));
CREATE TABLE public.festival_stage_changeovers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,stage_id uuid NOT NULL REFERENCES public.festival_stages(id),previous_performance_id uuid REFERENCES public.festival_artist_performance_slots(id),next_performance_id uuid REFERENCES public.festival_artist_performance_slots(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,required_minutes integer NOT NULL CHECK(required_minutes>0),planned_minutes integer NOT NULL CHECK(planned_minutes>=required_minutes),complexity_score integer NOT NULL CHECK(complexity_score BETWEEN 0 AND 100),status text NOT NULL DEFAULT 'planned',issues jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_stage_manager_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,stage_id uuid NOT NULL REFERENCES public.festival_stages(id),festival_date date NOT NULL,manager_source text NOT NULL CHECK(manager_source IN('player','npc')),profile_id uuid REFERENCES public.profiles(id),npc_staff_assignment_id uuid REFERENCES public.festival_staff_assignments(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,authority_scope text[] NOT NULL DEFAULT ARRAY['view_schedule'],status text NOT NULL DEFAULT 'assigned' CHECK(status IN('assigned','removed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),assignment_version integer NOT NULL DEFAULT 1,CHECK(num_nonnulls(profile_id,npc_staff_assignment_id)=1),CHECK(starts_at<ends_at));
CREATE TABLE public.festival_operational_schedule_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,festival_date date,department_id uuid REFERENCES public.festival_departments(id),stage_id uuid REFERENCES public.festival_stages(id),supplier_contract_id uuid REFERENCES public.festival_supplier_contracts(id),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,item_type text NOT NULL CHECK(item_type IN('site_setup','stage_construction','stage_test','sound_test','lighting_test','power_test','security_sweep','medical_setup','gate_setup','bar_setup','catering_setup','accessibility_setup','transport_setup','parking_setup','camping_setup','cleaning','waste_collection','site_reset','site_close','emergency_drill')),required_coverage integer,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(starts_at<ends_at));
CREATE TABLE public.festival_supplier_delivery_windows(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,supplier_contract_id uuid NOT NULL REFERENCES public.festival_supplier_contracts(id),supplier_requirement_id uuid REFERENCES public.festival_supplier_requirements(id),delivery_type text NOT NULL CHECK(delivery_type IN('initial_delivery','setup','replenishment','service_window','collection','load_out','emergency_callout')),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,location_type text,stage_id uuid REFERENCES public.festival_stages(id),status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(starts_at<ends_at));
CREATE TABLE public.festival_sponsor_activation_windows(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,sponsor_contract_id uuid NOT NULL REFERENCES public.festival_sponsor_contracts(id),sponsor_deliverable_id uuid REFERENCES public.festival_sponsor_deliverables(id),branding_placement_id uuid REFERENCES public.festival_branding_placements(id),activation_type text NOT NULL CHECK(activation_type IN('site_activation','VIP_hospitality','media_mention','Twaater_post','RockMundo_FM_mention','stage_naming','artist_interview','giveaway','product_sampling')),starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,location_reference text,status text NOT NULL DEFAULT 'planned' CHECK(status IN('planned','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(starts_at<ends_at));
CREATE TABLE public.festival_schedule_conflicts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,code text NOT NULL,category text NOT NULL,severity text NOT NULL CHECK(severity IN('info','warning','blocking')),blocking boolean NOT NULL,entity_type text,entity_id uuid,starts_at timestamptz,ends_at timestamptz,section text NOT NULL,message_key text NOT NULL,safe_metadata jsonb NOT NULL DEFAULT '{}',active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),resolved_at timestamptz);
CREATE TABLE public.festival_readiness_assessments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid UNIQUE NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,overall_score integer NOT NULL DEFAULT 0,identity_score integer NOT NULL DEFAULT 0,site_score integer NOT NULL DEFAULT 0,ticket_score integer NOT NULL DEFAULT 0,artist_score integer NOT NULL DEFAULT 0,operations_score integer NOT NULL DEFAULT 0,sponsorship_score integer NOT NULL DEFAULT 0,timetable_score integer NOT NULL DEFAULT 0,safety_score integer NOT NULL DEFAULT 0,finance_score integer NOT NULL DEFAULT 0,risk_score integer NOT NULL DEFAULT 0,blocking_count integer NOT NULL DEFAULT 0,warning_count integer NOT NULL DEFAULT 0,formula_version integer NOT NULL DEFAULT 1,financial_snapshot jsonb NOT NULL DEFAULT '{}',risk_assessment jsonb NOT NULL DEFAULT '[]',calculated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_readiness_checks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_readiness_assessment_id uuid NOT NULL REFERENCES public.festival_readiness_assessments(id) ON DELETE CASCADE,check_code text NOT NULL,group_code text NOT NULL,status text NOT NULL CHECK(status IN('passed','warning','failed','not_applicable')),blocking boolean NOT NULL,message_key text NOT NULL,entity_type text,entity_id uuid,safe_metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE public.festival_readiness_snapshots(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id),snapshot_version integer NOT NULL,configuration_snapshot jsonb NOT NULL,site_snapshot jsonb NOT NULL,ticket_snapshot jsonb NOT NULL,artist_snapshot jsonb NOT NULL,operations_snapshot jsonb NOT NULL,sponsorship_snapshot jsonb NOT NULL,timetable_snapshot jsonb NOT NULL,finance_snapshot jsonb NOT NULL,risk_snapshot jsonb NOT NULL,readiness_snapshot jsonb NOT NULL,formula_versions jsonb NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),created_by_profile_id uuid NOT NULL REFERENCES public.profiles(id),UNIQUE(festival_timetable_plan_id,snapshot_version));
CREATE TABLE public.festival_timetable_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id) ON DELETE CASCADE,caller_profile_id uuid NOT NULL REFERENCES public.profiles(id),idempotency_key uuid NOT NULL,payload_hash text NOT NULL,result jsonb,status text NOT NULL DEFAULT 'processing',created_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz,UNIQUE(festival_timetable_plan_id,caller_profile_id,idempotency_key));
CREATE TABLE public.festival_timetable_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),festival_timetable_plan_id uuid NOT NULL REFERENCES public.festival_timetable_plans(id),actor_profile_id uuid REFERENCES public.profiles(id),event_type text NOT NULL,entity_type text,entity_id uuid,previous_version integer,new_version integer,safe_metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());

CREATE OR REPLACE FUNCTION public._festival_timetable_authorised(c uuid,a uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT EXISTS(SELECT 1 FROM public.festival_companies f WHERE f.id=c AND f.owner_profile_id=a) OR coalesce(public.has_role(auth.uid(),'admin'::public.app_role),false) $$;
CREATE OR REPLACE FUNCTION public._festival_timetable_result(c uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$ SELECT jsonb_build_object('festivalCompanyId',p.festival_company_id,'festivalSummary',jsonb_build_object('name',cfg.public_name,'startDate',cfg.planned_start_date,'endDate',cfg.planned_end_date),'timezone',p.timezone,'status',p.status,'planningVersion',p.planning_version,'updatedAt',p.updated_at,'days',coalesce((SELECT jsonb_agg(to_jsonb(x) ORDER BY x.day_number) FROM public.festival_timetable_days x WHERE x.festival_timetable_plan_id=p.id),'[]'),'stageWindows',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_stage_operating_windows x JOIN public.festival_timetable_days d ON d.id=x.festival_timetable_day_id WHERE d.festival_timetable_plan_id=p.id),'[]'),'stageSlots',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_stage_slots x WHERE x.festival_timetable_plan_id=p.id),'[]'),'artistAllocations',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_artist_performance_slots x WHERE x.festival_timetable_plan_id=p.id),'[]'),'soundchecks',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_artist_soundchecks x WHERE x.festival_timetable_plan_id=p.id),'[]'),'changeovers',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_stage_changeovers x WHERE x.festival_timetable_plan_id=p.id),'[]'),'stageManagers',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_stage_manager_assignments x WHERE x.festival_timetable_plan_id=p.id AND x.status='assigned'),'[]'),'operationalItems',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_operational_schedule_items x WHERE x.festival_timetable_plan_id=p.id AND x.status='planned'),'[]'),'supplierWindows',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_supplier_delivery_windows x WHERE x.festival_timetable_plan_id=p.id AND x.status='planned'),'[]'),'sponsorActivationWindows',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_sponsor_activation_windows x WHERE x.festival_timetable_plan_id=p.id AND x.status='planned'),'[]'),'conflicts',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_schedule_conflicts x WHERE x.festival_timetable_plan_id=p.id AND x.active),'[]'),'readinessAssessment',(SELECT to_jsonb(x) FROM public.festival_readiness_assessments x WHERE x.festival_timetable_plan_id=p.id),'readinessChecks',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_readiness_checks x JOIN public.festival_readiness_assessments a ON a.id=x.festival_readiness_assessment_id WHERE a.festival_timetable_plan_id=p.id),'[]'),'permissions',jsonb_build_object('canManageFestival',true,'canComplete',true,'stageManagerStageIds','[]'::jsonb)) FROM public.festival_timetable_plans p JOIN public.festival_configurations cfg ON cfg.festival_company_id=p.festival_company_id WHERE p.festival_company_id=c $$;
CREATE OR REPLACE FUNCTION public.get_festival_timetable_plan(p_festival_company_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();s public.festival_sponsorship_plans%ROWTYPE;cfg public.festival_configurations%ROWTYPE;sp public.festival_site_plans%ROWTYPE;p public.festival_timetable_plans%ROWTYPE; BEGIN IF NOT public._festival_timetable_authorised(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_timetable_forbidden' USING ERRCODE='P0001';END IF;SELECT * INTO s FROM public.festival_sponsorship_plans WHERE festival_company_id=p_festival_company_id;IF s.status<>'ready_for_final_readiness' THEN RAISE EXCEPTION 'festival_timetable_not_unlocked' USING ERRCODE='P0001';END IF;SELECT * INTO cfg FROM public.festival_configurations WHERE festival_company_id=p_festival_company_id;SELECT * INTO sp FROM public.festival_site_plans WHERE festival_company_id=p_festival_company_id;INSERT INTO public.festival_timetable_plans(festival_company_id,sponsorship_plan_id,timezone,status) VALUES(p_festival_company_id,s.id,sp.timezone,'structure_generated') ON CONFLICT(festival_company_id) DO NOTHING RETURNING * INTO p;SELECT * INTO p FROM public.festival_timetable_plans WHERE festival_company_id=p_festival_company_id;INSERT INTO public.festival_timetable_days(festival_timetable_plan_id,festival_date,day_number,status) SELECT p.id,d::date,(d::date-cfg.planned_start_date)+1,'planned' FROM generate_series(cfg.planned_start_date,cfg.planned_end_date,'1 day') d ON CONFLICT DO NOTHING;RETURN public._festival_timetable_result(p_festival_company_id);END $$;
CREATE OR REPLACE FUNCTION public.save_festival_timetable_plan(p_festival_company_id uuid,p_expected_version integer,p_plan jsonb,p_stage_windows jsonb,p_slots jsonb,p_idempotency_key uuid,p_complete boolean DEFAULT false) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE a uuid:=public._caller_profile_id();p public.festival_timetable_plans%ROWTYPE;BEGIN IF p_complete THEN RAISE EXCEPTION 'festival_readiness_incomplete' USING ERRCODE='P0001';END IF;IF NOT public._festival_timetable_authorised(p_festival_company_id,a) THEN RAISE EXCEPTION 'festival_timetable_forbidden' USING ERRCODE='P0001';END IF;SELECT * INTO p FROM public.festival_timetable_plans WHERE festival_company_id=p_festival_company_id FOR UPDATE;IF p.planning_version<>p_expected_version THEN RAISE EXCEPTION 'festival_timetable_stale' USING ERRCODE='P0001';END IF;UPDATE public.festival_timetable_plans SET weather_contingencies=coalesce(p_plan->'weatherContingencies',weather_contingencies),planning_version=planning_version+1,updated_at=now() WHERE id=p.id;INSERT INTO public.festival_timetable_audit(festival_timetable_plan_id,actor_profile_id,event_type,previous_version,new_version) VALUES(p.id,a,'aggregate_saved',p.planning_version,p.planning_version+1);RETURN public._festival_timetable_result(p_festival_company_id);END $$;
CREATE OR REPLACE FUNCTION public._festival_timetable_planning_action(p_action text,p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE c uuid:=(p_payload->>'festivalCompanyId')::uuid;a uuid:=public._caller_profile_id();p public.festival_timetable_plans%ROWTYPE;q public.festival_timetable_requests%ROWTYPE;h text:=encode(digest(p_action||p_payload::text,'sha256'),'hex');BEGIN SELECT * INTO p FROM public.festival_timetable_plans WHERE festival_company_id=c FOR UPDATE;IF NOT public._festival_timetable_authorised(c,a) THEN RAISE EXCEPTION 'festival_timetable_forbidden' USING ERRCODE='P0001';END IF;IF p.planning_version<>coalesce((p_payload->>'expectedVersion')::int,p.planning_version) THEN RAISE EXCEPTION 'festival_timetable_stale' USING ERRCODE='P0001';END IF;INSERT INTO public.festival_timetable_requests(festival_timetable_plan_id,caller_profile_id,idempotency_key,payload_hash) VALUES(p.id,a,p_idempotency_key,h) ON CONFLICT DO NOTHING;SELECT * INTO q FROM public.festival_timetable_requests WHERE festival_timetable_plan_id=p.id AND caller_profile_id=a AND idempotency_key=p_idempotency_key FOR UPDATE;IF q.payload_hash<>h THEN RAISE EXCEPTION 'festival_timetable_idempotency_conflict' USING ERRCODE='P0001';END IF;IF q.status='succeeded' THEN RETURN q.result;END IF;
IF p_action='lock_festival_stage_slot' THEN UPDATE public.festival_stage_slots SET status='locked',slot_version=slot_version+1,updated_at=now() WHERE id=(p_payload->>'stageSlotId')::uuid AND festival_timetable_plan_id=p.id AND status='planned';
ELSIF p_action='unlock_festival_stage_slot' THEN UPDATE public.festival_stage_slots SET status='planned',slot_version=slot_version+1,updated_at=now() WHERE id=(p_payload->>'stageSlotId')::uuid AND festival_timetable_plan_id=p.id AND status='locked';
ELSIF p_action LIKE 'cancel_festival_%' OR p_action IN('remove_festival_artist_from_slot','remove_festival_stage_manager') THEN
 CASE p_action WHEN 'remove_festival_artist_from_slot' THEN UPDATE public.festival_artist_performance_slots SET performance_status='removed',allocation_version=allocation_version+1,updated_at=now() WHERE id=(p_payload->>'performanceSlotId')::uuid AND festival_timetable_plan_id=p.id;
 WHEN 'remove_festival_stage_manager' THEN UPDATE public.festival_stage_manager_assignments SET status='removed',assignment_version=assignment_version+1,updated_at=now() WHERE id=(p_payload->>'assignmentId')::uuid AND festival_timetable_plan_id=p.id;
 WHEN 'cancel_festival_operational_item' THEN UPDATE public.festival_operational_schedule_items SET status='cancelled',updated_at=now() WHERE id=(p_payload->>'itemId')::uuid AND festival_timetable_plan_id=p.id;
 WHEN 'cancel_festival_supplier_delivery' THEN UPDATE public.festival_supplier_delivery_windows SET status='cancelled',updated_at=now() WHERE id=(p_payload->>'windowId')::uuid AND festival_timetable_plan_id=p.id;
 WHEN 'cancel_festival_sponsor_activation' THEN UPDATE public.festival_sponsor_activation_windows SET status='cancelled',updated_at=now() WHERE id=(p_payload->>'windowId')::uuid AND festival_timetable_plan_id=p.id; ELSE NULL;END CASE;
END IF;
UPDATE public.festival_timetable_plans SET planning_version=planning_version+1,updated_at=now() WHERE id=p.id;INSERT INTO public.festival_timetable_audit(festival_timetable_plan_id,actor_profile_id,event_type,previous_version,new_version,safe_metadata) VALUES(p.id,a,p_action,p.planning_version,p.planning_version+1,jsonb_build_object('idempotencyKey',p_idempotency_key));q.result:=public._festival_timetable_result(c);UPDATE public.festival_timetable_requests SET status='succeeded',result=q.result,completed_at=now() WHERE id=q.id;RETURN q.result;END $$;
CREATE OR REPLACE FUNCTION public.generate_festival_timetable_suggestions(p_festival_company_id uuid,p_expected_version integer,p_generation_mode text,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ BEGIN IF p_generation_mode NOT IN('fill_empty_slots','rebalance','full_regeneration') THEN RAISE EXCEPTION 'festival_timetable_generation_invalid';END IF;RETURN jsonb_build_object('mode',p_generation_mode,'planningVersion',p_expected_version,'proposedChanges','[]'::jsonb,'lockedSlotsPreserved',true,'requiresConfirmation',p_generation_mode='full_regeneration');END $$;
CREATE OR REPLACE FUNCTION public.assign_festival_artist_to_slot(p_payload jsonb,p_idempotency_key uuid) RETURNS jsonb LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT public._festival_timetable_planning_action('assign_festival_artist_to_slot',p_payload,p_idempotency_key) $$;
