CREATE OR REPLACE FUNCTION public.recalculate_festival_readiness(p_festival_company_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE p public.festival_timetable_plans%ROWTYPE;b int;w int;BEGIN SELECT * INTO p FROM public.festival_timetable_plans WHERE festival_company_id=p_festival_company_id FOR UPDATE;IF NOT public._festival_timetable_authorised(p_festival_company_id,public._caller_profile_id()) THEN RAISE EXCEPTION 'festival_timetable_forbidden';END IF;IF p.planning_version<>p_expected_version THEN RAISE EXCEPTION 'festival_timetable_stale';END IF;SELECT count(*) FILTER(WHERE blocking),count(*) FILTER(WHERE severity='warning') INTO b,w FROM public.festival_schedule_conflicts WHERE festival_timetable_plan_id=p.id AND active;INSERT INTO public.festival_readiness_assessments(festival_timetable_plan_id,overall_score,blocking_count,warning_count,timetable_score,safety_score,finance_score,risk_score,financial_snapshot,risk_assessment) VALUES(p.id,CASE WHEN b=0 THEN 100 ELSE greatest(0,100-b*10) END,b,w,CASE WHEN b=0 THEN 100 ELSE 50 END,CASE WHEN EXISTS(SELECT 1 FROM public.festival_schedule_conflicts WHERE festival_timetable_plan_id=p.id AND active AND category='safety') THEN 0 ELSE 100 END,100,greatest(0,100-w*5),jsonb_build_object('cashIsDistinctFromForecast',true,'receivablesCountAsCash',false,'transfersMade',false),'[]') ON CONFLICT(festival_timetable_plan_id) DO UPDATE SET overall_score=excluded.overall_score,blocking_count=excluded.blocking_count,warning_count=excluded.warning_count,timetable_score=excluded.timetable_score,safety_score=excluded.safety_score,finance_score=excluded.finance_score,risk_score=excluded.risk_score,calculated_at=now();RETURN public._festival_timetable_result(p_festival_company_id);END $$;
CREATE OR REPLACE FUNCTION public.complete_festival_timetable_plan(p_festival_company_id uuid,p_expected_version integer,p_idempotency_key uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$ DECLARE p public.festival_timetable_plans%ROWTYPE;a uuid:=public._caller_profile_id();r public.festival_readiness_assessments%ROWTYPE;BEGIN PERFORM public.recalculate_festival_readiness(p_festival_company_id,p_expected_version,p_idempotency_key);SELECT * INTO p FROM public.festival_timetable_plans WHERE festival_company_id=p_festival_company_id FOR UPDATE;SELECT * INTO r FROM public.festival_readiness_assessments WHERE festival_timetable_plan_id=p.id;IF r.blocking_count>0 OR EXISTS(SELECT 1 FROM public.festival_stages s JOIN public.festival_site_plans sp ON sp.id=s.festival_site_plan_id WHERE sp.festival_company_id=p_festival_company_id AND s.status='ready' AND NOT EXISTS(SELECT 1 FROM public.festival_stage_operating_windows w JOIN public.festival_timetable_days d ON d.id=w.festival_timetable_day_id WHERE d.festival_timetable_plan_id=p.id AND w.stage_id=s.id)) THEN RAISE EXCEPTION 'festival_readiness_incomplete' USING ERRCODE='P0001';END IF;UPDATE public.festival_timetable_plans SET status='ready_for_launch_preparation',completed_at=now(),updated_at=now() WHERE id=p.id;INSERT INTO public.festival_readiness_snapshots(festival_timetable_plan_id,snapshot_version,configuration_snapshot,site_snapshot,ticket_snapshot,artist_snapshot,operations_snapshot,sponsorship_snapshot,timetable_snapshot,finance_snapshot,risk_snapshot,readiness_snapshot,formula_versions,created_by_profile_id) SELECT p.id,p.planning_version,to_jsonb(c),to_jsonb(s),'{}',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM public.festival_artist_performance_slots x WHERE x.festival_timetable_plan_id=p.id),'[]'),'{}','{}',public._festival_timetable_result(p_festival_company_id),r.financial_snapshot,r.risk_assessment,to_jsonb(r),jsonb_build_object('readiness',p.readiness_formula_version,'generation',p.schedule_generation_version),a FROM public.festival_configurations c JOIN public.festival_site_plans s ON s.festival_company_id=c.festival_company_id WHERE c.festival_company_id=p_festival_company_id ON CONFLICT DO NOTHING;INSERT INTO public.festival_timetable_audit(festival_timetable_plan_id,actor_profile_id,event_type,safe_metadata) VALUES(p.id,a,'timetable_plan_complete',jsonb_build_object('message','Festival timetable and readiness planning are complete. The Festival can now proceed to launch preparation.','publicLaunch',false,'payments',false));RETURN public._festival_timetable_result(p_festival_company_id);END $$;

DO $$ DECLARE t text;BEGIN FOREACH t IN ARRAY ARRAY['festival_timetable_plans','festival_timetable_days','festival_stage_operating_windows','festival_stage_slots','festival_artist_performance_slots','festival_artist_soundchecks','festival_stage_changeovers','festival_stage_manager_assignments','festival_operational_schedule_items','festival_supplier_delivery_windows','festival_sponsor_activation_windows','festival_schedule_conflicts','festival_readiness_assessments','festival_readiness_checks','festival_readiness_snapshots','festival_timetable_requests','festival_timetable_audit'] LOOP EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC,anon,authenticated',t);END LOOP;END $$;
REVOKE ALL ON FUNCTION public._festival_timetable_planning_action(text,jsonb,uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.get_festival_timetable_plan(uuid),public.save_festival_timetable_plan(uuid,integer,jsonb,jsonb,jsonb,uuid,boolean),public.generate_festival_timetable_suggestions(uuid,integer,text,uuid),public.recalculate_festival_readiness(uuid,integer,uuid),public.complete_festival_timetable_plan(uuid,integer,uuid) TO authenticated;
